const cofre = (function () {
  let valor = 0; // vive apenas dentro da IIFE

  return {
    guardar: function () {
      valor += 1;
      return valor;
    },
    ver: function () {
      return valor;
    },
  };
})();

console.log(cofre.ver());      // 0
console.log(cofre.guardar());  // 1
console.log(cofre.guardar());  // 2
console.log(cofre.ver());      // 2
console.log(cofre.valor);      // undefined — a porta está trancada

// Passo 1 e 2: a IIFE roda na hora e guarda o estado internamente.
const registro = (function () {
  const configuracoes = { tema: 'claro', volume: 70 };

  // Passo 3: expomos só o mínimo, com proteções.
  return {
    obter: function () {
      return { ...configuracoes }; // cópia: o original não pode ser editado de fora
    },
    definir: function (chave, valor) {
      if (!(chave in configuracoes)) {
        throw new Error(`configuração desconhecida: ${chave}`);
      }
      configuracoes[chave] = valor;
    },
  };
})();

// Passo 4: quem usa só tem as portas obter/definir.
registro.definir('tema', 'escuro');

// Passo 5: a cópia não vaza mudanças para dentro da IIFE.
const copia = registro.obter();
copia.tema = 'bagunçado';
console.log(registro.obter().tema); // 'escuro' — a bagunça ficou só na cópia
